discrete SCADA
port:
    event input real START_DATA_COLLECTION;
    event output real DATA_COLLECTED;
state:
    initial state State1
        when entry() then
            statehold(5);
        end;

        when receive(START_DATA_COLLECTION) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(10);
        end;

        when timeover() then
            transition(State1);
            out
                send(DATA_COLLECTED, 1);
        end;
    end;
end;
end;

